1	-- Operation Empower B1.2 (forward-only): the Partner Academy.
2	-- A course is a B1.1 content item of kind 'course'. Its structure (category, objectives, ordered modules, ordered lesson
3	-- references) lives in the course version's `fields`, so it is versioned, reviewed, approved, published, superseded and
4	-- withdrawn exactly like every other item, and it is immutable from submission. This migration adds:
5	--   * the 'course' kind (partner-only) and a database check that course structure references real lesson items;
6	--   * private, append-only partner learning records: lesson completions and knowledge-check attempts, each accepted only
7	--     while the lesson and course are actually published, in date and linked;
8	--   * a per-course "continue where you left off" pointer.
9	-- Learning records have no relation to any commercial table. Dates are UTC.
10	
11	ALTER TABLE empower_content_items DROP CONSTRAINT empower_content_items_kind_check;
12	ALTER TABLE empower_content_items ADD CONSTRAINT empower_content_items_kind_check CHECK (kind IN ('resource','lesson','knowledge','objection','template','course'));
13	ALTER TABLE empower_content_items ADD CONSTRAINT empower_content_items_course_partner_only CHECK (kind <> 'course' OR audience = 'partner_only');
14	
15	-- Lesson item ids referenced by a course version, in order.
16	CREATE FUNCTION empower_course_lesson_ids(structure jsonb) RETURNS uuid[] LANGUAGE sql IMMUTABLE AS $$
17	  SELECT coalesce(array_agg(l.value::uuid ORDER BY m.ord, l.ord), '{}')
18	  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(structure->'modules') = 'array' THEN structure->'modules' ELSE '[]'::jsonb END) WITH ORDINALITY m(value, ord),
19	       jsonb_array_elements_text(CASE WHEN jsonb_typeof(m.value->'lessons') = 'array' THEN m.value->'lessons' ELSE '[]'::jsonb END) WITH ORDINALITY l(value, ord)
20	$$;
21	
22	CREATE FUNCTION empower_course_structure_guard() RETURNS trigger LANGUAGE plpgsql AS $$
23	DECLARE kind text; ids uuid[];
24	BEGIN
25	  SELECT i.kind INTO kind FROM empower_content_items i WHERE i.id = NEW.item_id;
26	  IF kind <> 'course' THEN RETURN NEW; END IF;
27	  IF NEW.fields ? 'modules' AND jsonb_typeof(NEW.fields->'modules') <> 'array' THEN RAISE EXCEPTION 'Course modules must be a list'; END IF;
28	  ids := empower_course_lesson_ids(NEW.fields);
29	  IF cardinality(ids) <> (SELECT count(DISTINCT x) FROM unnest(ids) x) THEN RAISE EXCEPTION 'A lesson can appear only once in a course'; END IF;
30	  IF EXISTS (SELECT 1 FROM unnest(ids) x LEFT JOIN empower_content_items i ON i.id = x WHERE i.id IS NULL OR i.kind <> 'lesson') THEN
31	    RAISE EXCEPTION 'A course may reference only existing lesson items';
32	  END IF;
33	  RETURN NEW;
34	END $$;
35	-- Runs after the B1.1 lifecycle guard (trigger names sort alphabetically), so immutability is checked first.
36	CREATE TRIGGER empower_course_structure_guard BEFORE INSERT OR UPDATE OF fields ON empower_content_versions FOR EACH ROW EXECUTE FUNCTION empower_course_structure_guard();
37	
38	-- True when the lesson version is the published, in-date version of a lesson that the published, in-date course version links.
39	CREATE FUNCTION empower_academy_lesson_servable(course_version uuid, lesson_version uuid) RETURNS boolean LANGUAGE sql STABLE AS $$
40	  SELECT EXISTS (
41	    SELECT 1 FROM empower_content_versions cv JOIN empower_content_items ci ON ci.id = cv.item_id AND ci.kind = 'course'
42	      JOIN empower_content_versions lv ON lv.id = lesson_version JOIN empower_content_items li ON li.id = lv.item_id AND li.kind = 'lesson'
43	    WHERE cv.id = course_version
44	      AND cv.status = 'published' AND cv.review_by >= (now() AT TIME ZONE 'UTC')::date
45	      AND lv.status = 'published' AND lv.review_by >= (now() AT TIME ZONE 'UTC')::date
46	      AND li.id = ANY (empower_course_lesson_ids(cv.fields)))
47	$$;
48	
49	CREATE TABLE empower_academy_completions (
50	 id uuid PRIMARY KEY,
51	 partner_id uuid NOT NULL REFERENCES expansion_partners(id),
52	 course_version_id uuid NOT NULL REFERENCES empower_content_versions(id),
53	 lesson_version_id uuid NOT NULL REFERENCES empower_content_versions(id),
54	 completed_at timestamptz NOT NULL DEFAULT now(),
55	 -- A completion belongs to the exact lesson version read; it is recorded once however often "complete" is pressed.
56	 UNIQUE (partner_id, lesson_version_id)
57	);
58	CREATE INDEX empower_academy_completions_partner ON empower_academy_completions(partner_id, completed_at);
59	
60	CREATE TABLE empower_academy_check_attempts (
61	 id uuid PRIMARY KEY,
62	 partner_id uuid NOT NULL REFERENCES expansion_partners(id),
63	 course_version_id uuid NOT NULL REFERENCES empower_content_versions(id),
64	 lesson_version_id uuid NOT NULL REFERENCES empower_content_versions(id),
65	 question_id text NOT NULL CHECK (question_id ~ '^q[0-9]{1,2}$'),
66	 answer jsonb NOT NULL CHECK (jsonb_typeof(answer) = 'array' AND jsonb_array_length(answer) BETWEEN 1 AND 6),
67	 correct boolean NOT NULL,
68	 attempted_at timestamptz NOT NULL DEFAULT now()
69	);
70	CREATE INDEX empower_academy_attempts_partner ON empower_academy_check_attempts(partner_id, lesson_version_id, attempted_at);
71	
72	CREATE FUNCTION empower_academy_record_guard() RETURNS trigger LANGUAGE plpgsql AS $$
73	BEGIN
74	  IF NOT empower_academy_lesson_servable(NEW.course_version_id, NEW.lesson_version_id) THEN
75	    RAISE EXCEPTION 'This lesson is not currently available';
76	  END IF;
77	  IF TG_TABLE_NAME = 'empower_academy_completions' THEN NEW.completed_at := now(); ELSE NEW.attempted_at := now(); END IF;
78	  RETURN NEW;
79	END $$;
80	CREATE TRIGGER empower_academy_completion_guard BEFORE INSERT ON empower_academy_completions FOR EACH ROW EXECUTE FUNCTION empower_academy_record_guard();
81	CREATE TRIGGER empower_academy_attempt_guard BEFORE INSERT ON empower_academy_check_attempts FOR EACH ROW EXECUTE FUNCTION empower_academy_record_guard();
82	CREATE TRIGGER empower_academy_completions_immutable BEFORE UPDATE OR DELETE ON empower_academy_completions FOR EACH ROW EXECUTE FUNCTION commercial_history_immutable();
83	CREATE TRIGGER empower_academy_attempts_immutable BEFORE UPDATE OR DELETE ON empower_academy_check_attempts FOR EACH ROW EXECUTE FUNCTION commercial_history_immutable();
84	
85	CREATE TABLE empower_academy_course_state (
86	 partner_id uuid NOT NULL REFERENCES expansion_partners(id),
87	 course_item_id uuid NOT NULL REFERENCES empower_content_items(id),
88	 last_lesson_item_id uuid NOT NULL REFERENCES empower_content_items(id),
89	 last_viewed_at timestamptz NOT NULL DEFAULT now(),
90	 PRIMARY KEY (partner_id, course_item_id)
91	);
